CREATE TABLE IF NOT EXISTS stations (id BIGSERIAL PRIMARY KEY, code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, city TEXT NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trains (id BIGSERIAL PRIMARY KEY, train_number TEXT UNIQUE NOT NULL, train_name TEXT NOT NULL, provider_mode TEXT NOT NULL DEFAULT 'demo', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS train_schedules (id BIGSERIAL PRIMARY KEY, train_id BIGINT NOT NULL REFERENCES trains(id), from_station_id BIGINT NOT NULL REFERENCES stations(id), to_station_id BIGINT NOT NULL REFERENCES stations(id), departure_time TEXT NOT NULL, arrival_time TEXT NOT NULL, duration_minutes INTEGER NOT NULL, days TEXT NOT NULL DEFAULT 'Daily', fare_inr NUMERIC(10,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_schedules_stations ON train_schedules(from_station_id, to_station_id);
CREATE TABLE IF NOT EXISTS bookings (id BIGSERIAL PRIMARY KEY, booking_ref TEXT UNIQUE NOT NULL, user_id TEXT NOT NULL, origin TEXT NOT NULL, destination TEXT NOT NULL, travel_date DATE NOT NULL, train_name TEXT NOT NULL, train_number TEXT NOT NULL, departure_time TEXT NOT NULL, arrival_time TEXT NOT NULL, duration_minutes INTEGER NOT NULL, transfers INTEGER NOT NULL DEFAULT 0, fare_inr NUMERIC(10,2), status TEXT NOT NULL DEFAULT 'PENDING_CONFIRMATION', provider_mode TEXT NOT NULL DEFAULT 'DEMO', passengers JSONB NOT NULL DEFAULT '[]'::jsonb, status_history JSONB NOT NULL DEFAULT '[]'::jsonb, idempotency_key TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_bookings_user_date ON bookings(user_id, travel_date DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_bookings_idempotency ON bookings(user_id, idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS notifications (id BIGSERIAL PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'info', is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS route_searches (id BIGSERIAL PRIMARY KEY, user_id TEXT, origin TEXT NOT NULL, destination TEXT NOT NULL, travel_date DATE, preferences JSONB NOT NULL DEFAULT '{}'::jsonb, source TEXT NOT NULL DEFAULT 'demo', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id BIGSERIAL PRIMARY KEY, user_id TEXT, title TEXT NOT NULL DEFAULT 'RailMate conversation', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_messages (id BIGSERIAL PRIMARY KEY, conversation_id BIGINT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_execution_logs (id BIGSERIAL PRIMARY KEY, agent_name TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL, detail JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, user_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, detail JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
